--
-- Table structure for table `staging_residents`
--

DROP TABLE IF EXISTS `staging_residents`;
CREATE TABLE IF NOT EXISTS `staging_residents` (
  `staging_id` int NOT NULL AUTO_INCREMENT,
  `street` varchar(100) DEFAULT NULL,
  `last_name` varchar(45) DEFAULT NULL,
  `first_name` varchar(45) DEFAULT NULL,
  `middle_name` varchar(45) DEFAULT NULL,
  `relationship_to_hh` varchar(100) DEFAULT NULL,
  `house_number` varchar(45) DEFAULT NULL,
  `date_of_birth` varchar(30) DEFAULT NULL,
  `sex` varchar(50) DEFAULT NULL,
  `marital_status` varchar(100) DEFAULT NULL,
  `source_of_income` varchar(100) DEFAULT NULL,
  `ethnicity` varchar(100) DEFAULT NULL,
  `religion` varchar(100) DEFAULT NULL,
  `normalized_relationship_id` int DEFAULT NULL,
  `normalized_marital_status_id` int DEFAULT NULL,
  `normalized_source_of_income_id` int DEFAULT NULL,
  `normalized_sex_id` int DEFAULT NULL,
  `normalized_ethnicity_id` int DEFAULT NULL,
  `normalized_religion_id` int DEFAULT NULL,
  `normalized_house_number` varchar(255) DEFAULT NULL,
  `normalized_date_of_birth` date DEFAULT NULL,
  PRIMARY KEY (`staging_id`)
) ENGINE=MyISAM AUTO_INCREMENT=3460 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

